function refreshDrawerButtons(){$('#drawerButtons').innerHTML=drawers.map((d,i)=>`<button data-drawer="${i}" aria-pressed="${d.open}">${'ABCDE'[i]} <span>${d.open?'Close':'Open'}</span></button>`).join('');$('#allDrawers').textContent=drawers.every(d=>d.open)?'Close all drawers':'Open all drawers';}
$('#drawerButtons').onclick=e=>{const b=e.target.closest('[data-drawer]');if(b)toggleDrawer(+b.dataset.drawer);};$('#allDrawers').onclick=()=>{const open=!drawers.every(d=>d.open);drawers.forEach(d=>d.open=open);refreshDrawerButtons();resetFocus();notify(open?'All five glass drawers opened':'All drawers closed');};refreshDrawerButtons();
let drawerPress=null;renderer.domElement.addEventListener('pointerdown',e=>drawerPress=[e.clientX,e.clientY],true);renderer.domElement.addEventListener('pointerup',e=>{if(!drawerPress||touchPointers.size>1||Math.hypot(e.clientX-drawerPress[0],e.clientY-drawerPress[1])>6)return;const rect=renderer.domElement.getBoundingClientRect();picker.setFromCamera(new THREE.Vector2((e.clientX-rect.left)/rect.width*2-1,-(e.clientY-rect.top)/rect.height*2+1),camera);const hits=picker.intersectObjects(drawers.map(d=>d.group),true);if(!hits.length||!environment.visible)return;let object=hits[0].object;if(object.userData.drawerHandle!==undefined){toggleDrawer(object.userData.drawerHandle);e.stopImmediatePropagation();return;}let product=object;while(product.parent&&!product.userData.productName&&product.userData.drawerIndex===undefined)product=product.parent;if(product.userData.productName){const i=drawers.findIndex(d=>{let p=product;while(p){if(p===d.group)return true;p=p.parent;}return false;});if(i>=0){focusItem(product,i,product.userData.productName);e.stopImmediatePropagation();return;}}const g=object;let parent=g;while(parent.parent&&parent.userData.drawerIndex===undefined)parent=parent.parent;if(parent.userData.drawerIndex!==undefined){toggleDrawer(parent.userData.drawerIndex);e.stopImmediatePropagation();}},true);
// Include newly-added drawer catalogue in tablet product interactions.
$('#tabletResults').addEventListener('click',e=>{const b=e.target.closest('[data-tablet-item="product"]');if(!b)return;const name=data[tabletDivision].products[+b.dataset.itemIndex];const product=productGroups.find(p=>p.userData.productName===name);if(product){drawers[tabletDivision].open=true;refreshDrawerButtons();focusItem(worlds[tabletDivision],tabletDivision,name+' / drawer sample');}});
// Mirror the complete original catalogue inside the front main counter's five vitrines.
bays.forEach((bay,i)=>{const replace=bay.children.filter(part=>part.position.y>.6&&part.position.y<.94&&part.material!==glass&&!(part.geometry?.type==='BoxGeometry'&&part.geometry.parameters.width<.02));replace.forEach(part=>bay.remove(part));const rack=new THREE.Group();rack.position.y=.61;bay.add(rack);data[i].products.forEach((name,j)=>{const cols=data[i].products.length>4?3:2;const rows=Math.ceil(data[i].products.length/cols);createMiniProduct(name,j,rack,(j%cols-(cols-1)/2)*(.51/cols),(Math.floor(j/cols)-(rows-1)/2)*.24,.53);});registerPart(rack,[0,.19,0]);});

// Round pedestal restored: compact elevated drawer fits inside the circular footprint.
worlds.forEach((world,i)=>{const squareShell=world.children.find(o=>o.userData.drawerShell);if(squareShell)world.remove(squareShell);const roundBase=new THREE.Group();world.add(roundBase);ring(.65,.65,.145,.018,drawerRail,roundBase);ring(.645,.645,.505,.014,drawerRail,roundBase);const roundWall=new THREE.Mesh(new THREE.CylinderGeometry(.635,.635,.34,96,1,true),drawerGlass);roundWall.position.y=.325;roundBase.add(roundWall);for(const angle of [-Math.PI/4,Math.PI/4,Math.PI*.75,Math.PI*1.25]){box(.012,.34,.012,drawerRail,Math.cos(angle)*.63,.325,Math.sin(angle)*.63,roundBase);}registerPart(roundBase,[0,.06,0]);const d=drawers[i];d.group.scale.set(1,1,1);d.home.y=.205;d.home.z=.08;d.group.position.copy(d.home);});

// Sharp selected counter over a softly blurred environment (independent render pass).
let isolationRoot=null,isolationCopies=[];
const isolatedScene=new THREE.Scene();
const isolateRenderer=new THREE.WebGLRenderer({alpha:true,antialias:true});isolateRenderer.setClearColor(0x000000,0);isolateRenderer.setPixelRatio(Math.min(devicePixelRatio,2));isolateRenderer.outputColorSpace=renderer.outputColorSpace;isolateRenderer.toneMapping=renderer.toneMapping;isolateRenderer.toneMappingExposure=renderer.toneMappingExposure;
isolateRenderer.domElement.className='isolated-counter-canvas';isolateRenderer.domElement.setAttribute('aria-hidden','true');host.appendChild(isolateRenderer.domElement);
renderer.domElement.classList.add('environment-canvas');
const isolatedLights=new THREE.Group();scene.children.filter(o=>o.isLight).forEach(light=>{const copy=light.clone();copy.castShadow=false;isolatedLights.add(copy);});isolatedScene.add(isolatedLights);
const exitIsolation=document.createElement('button');exitIsolation.className='exit-isolation hidden';exitIsolation.textContent='↶ Show full environment';exitIsolation.onclick=()=>{clearCounterIsolation();resetFocus();};$('.workspace').appendChild(exitIsolation);
function clearCounterIsolation(){if(typeof isolationRoot==='undefined')return;isolationRoot=null;document.body.classList.remove('counter-isolated');exitIsolation.classList.add('hidden');isolateRenderer.clear();isolationCopies.forEach(({copy})=>isolatedScene.remove(copy));isolationCopies=[];}
function setCounterIsolation(object){if(typeof isolationRoot==='undefined')return;let root=object;while(root&&!worlds.includes(root)&&root!==model)root=root.parent;if(!root)return;if(root===isolationRoot)return;clearCounterIsolation();isolationRoot=root;root.traverse(source=>{if(!source.isMesh&&!source.isLine&&!source.isLineSegments)return;const copy=source.clone(false);copy.matrixAutoUpdate=false;copy.castShadow=false;copy.receiveShadow=false;copy.frustumCulled=false;isolatedScene.add(copy);isolationCopies.push({source,copy});});document.body.classList.add('counter-isolated');exitIsolation.classList.remove('hidden');}
function renderCounterIsolation(){if(typeof isolationRoot==='undefined'||!isolationRoot)return;const width=host.clientWidth,height=host.clientHeight;const canvas=isolateRenderer.domElement;if(canvas.width!==Math.round(width*isolateRenderer.getPixelRatio())||canvas.height!==Math.round(height*isolateRenderer.getPixelRatio()))isolateRenderer.setSize(width,height);scene.updateMatrixWorld(true);isolationCopies.forEach(({source,copy})=>{copy.matrix.copy(source.matrixWorld);let ancestor=source,visible=true;while(ancestor&&ancestor!==scene){if(!ancestor.visible){visible=false;break;}ancestor=ancestor.parent;}copy.visible=visible;});isolateRenderer.render(isolatedScene,camera);}
$('#showroom').addEventListener('click',clearCounterIsolation);$('#counterOnly').addEventListener('click',clearCounterIsolation);$('#explode').addEventListener('click',clearCounterIsolation);
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!document.querySelector('dialog[open]'))clearCounterIsolation();});
